// UpsertApplications inserts or updates a applications record with domain-specific columns.
func (s *Store) UpsertApplications(data json.RawMessage) error {
	obj, err := DecodeJSONObject(data)
	if err != nil {
		return fmt.Errorf("unmarshaling applications: %w", err)
	}

	id := extractObjectID(obj)
	if id == "" {
		return fmt.Errorf("missing id for applications")
	}
	storageID := resourceStorageID("applications", id, obj)

	s.writeMu.Lock()
	defer s.writeMu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	if err := s.upsertGenericResourceTx(tx, "applications", storageID, data); err != nil {
		return err
	}
	if err := s.upsertApplicationsTx(tx, storageID, obj, data); err != nil {
		return err
	}

	return tx.Commit()
}

